mapper.select:
select * from `teacher`


        AND teacher_ID like concat('%',#{teacher_ID},'%')


        AND team_ID = #{team_ID}


        AND name like concat('%',#{name},'%')


        AND tele like concat('%',#{tele},'%')


        AND gender = #{gender}


        AND age = #{age}


order by teacher_ID asc

mapper.update:
update `teacher`
set team_ID = #{team_ID}, name = #{name}, password = #{password}, tele = #{tele},
    gender = #{gender}, age = #{age}
where teacher_ID = #{teacher_ID}
